mapper.update:
UPDATE NOTICE
   SET TITLE    = #{title},
       CONTENT  = #{content,  jdbcType=CLOB},
       IS_FIXED = #{is_fixed, jdbcType=VARCHAR}
 WHERE NOTICE_NUM = #{notice_num}

UPDATE NOTICE
   SET VIEW_COUNT = VIEW_COUNT + 1
 WHERE NOTICE_NUM = #{noticeNum}

UPDATE NOTICE
   SET IS_FIXED = CASE WHEN IS_FIXED = 'Y' THEN 'N' ELSE 'Y' END
 WHERE NOTICE_NUM = #{noticeNum}
